INSERT INTO "public"."foods" ("id","store_id","name","description","price","image_url","is_available","rating","sold_count","category_id") VALUES
('cc000001-0001-4000-a000-000000000001','bb000001-2222-4000-a000-000000000001','Cơm Tấm Sườn Bì Chả','Sườn nướng than hoa, bì heo, chả trứng, cơm tấm dẻo, mỡ hành.', 55000,'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=500',true,4.8,12000,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000002','bb000001-2222-4000-a000-000000000001','Cơm Tấm Sườn Nướng','Sườn heo ướp đậm vị nướng than, ăn kèm đồ chua, nước mắm.', 45000,'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=500',true,4.7,9500,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000003','bb000001-2222-4000-a000-000000000001','Cơm Gà Xối Mỡ','Gà giòn rụm, cơm dẻo thơm, nước sốt đặc biệt.', 60000,'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?w=500',true,4.6,7800,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000004','bb000001-2222-4000-a000-000000000001','Cơm Chiên Dương Châu','Cơm chiên cùng trứng, lạp xưởng, đậu Hà Lan, cà rốt.', 50000,'https://images.unsplash.com/photo-1603133872878-684f208fb84b?w=500',true,4.5,6200,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000005','bb000001-2222-4000-a000-000000000001','Cơm Bò Lúc Lắc','Thịt bò lúc lắc xào tỏi thơm phức, ăn kèm cơm nóng.', 75000,'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=500',true,4.9,4300,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000006','bb000001-2222-4000-a000-000000000001','Canh Chua Cá Lóc','Canh chua nấu với cá lóc tươi, dứa, cà chua, giá đỗ, rau thơm.', 35000,'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=500',true,4.4,3100,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000007','bb000001-2222-4000-a000-000000000001','Trứng Chiên','Trứng gà chiên ốp la vàng ươm, ăn kèm nước tương.', 10000,'https://images.unsplash.com/photo-1525351484163-7529414344d8?w=500',true,4.3,15000,'ca000001-0000-4000-a000-000000000001'),
('cc000001-0001-4000-a000-000000000008','bb000001-2222-4000-a000-000000000001','Đậu Hũ Sốt Cà','Đậu hũ chiên giòn sốt cà chua ngọt đậm vị.', 25000,'https://images.unsplash.com/photo-1546069901-d5bfd2cbfb1f?w=500',true,4.2,2800,'ca000001-0000-4000-a000-000000000009'),
('cc000001-0001-4000-a000-000000000009','bb000001-2222-4000-a000-000000000001','Nước Ngọt Lon','Coca-Cola / Pepsi / 7Up lon lạnh giải khát.', 15000,'https://images.unsplash.com/photo-1581636625402-29b2a704ef13?w=500',true,4.0,20000,'ca000001-0000-4000-a000-000000000003'),
('cc000001-0001-4000-a000-000000000010','bb000001-2222-4000-a000-000000000001','Chè Ba Màu','Chè ba màu mát lạnh với đậu xanh, đậu đỏ, thạch rau câu.', 20000,'https://images.unsplash.com/photo-1488477181946-6428a0291777?w=500',true,4.5,5600,'ca000001-0000-4000-a000-000000000010');
INSERT INTO "public"."foods" ("id","store_id","name","description","price","image_url","is_available","rating","sold_count","category_id") VALUES
('cc000002-0001-4000-a000-000000000001','bb000001-2222-4000-a000-000000000002','Bún Bò Huế Đặc Biệt','Bún bò giò heo, huyết, chả cua, sa tế cay nồng.', 65000,'https://images.unsplash.com/photo-1576577445504-6af96477db52?w=500',true,4.9,18000,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000002','bb000001-2222-4000-a000-000000000002','Bún Bò Thường','Bún bò tái, giò heo, nước dùng đậm đà hương vị Huế.', 50000,'https://images.unsplash.com/photo-1582878826629-29b7ad1cb438?w=500',true,4.7,14000,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000003','bb000001-2222-4000-a000-000000000002','Bún Riêu Cua','Bún riêu nấu từ cua đồng tươi, đậu phụ chiên, cà chua.', 45000,'https://images.unsplash.com/photo-1555126634-323283e090fa?w=500',true,4.6,11000,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000004','bb000001-2222-4000-a000-000000000002','Phở Bò Tái Chín','Bánh phở mềm dẻo, thịt bò tái chín, hành lá thơm nồng.', 55000,'https://images.unsplash.com/photo-1547592180-85f173990554?w=500',true,4.8,16000,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000005','bb000001-2222-4000-a000-000000000002','Bún Thịt Nướng','Bún tươi ăn kèm thịt heo nướng than hoa, rau sống, nước mắm chua ngọt.', 45000,'https://images.unsplash.com/photo-1626804475297-41607ea0d4eb?w=500',true,4.5,8500,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000006','bb000001-2222-4000-a000-000000000002','Bún Mọc','Bún mọc sườn, nấm hương, nước dùng thanh ngọt tự nhiên.', 40000,'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?w=500',true,4.4,6200,'ca000001-0000-4000-a000-000000000002'),
('cc000002-0001-4000-a000-000000000007','bb000001-2222-4000-a000-000000000002','Nem Cua Bể Chiên','Nem cua bể vỏ giòn rụm, nhân tôm thịt cua đậm đà.', 25000,'https://images.unsplash.com/photo-1580828369019-1813204cd1ce?w=500',true,4.6,9800,'ca000001-0000-4000-a000-000000000004'),
('cc000002-0001-4000-a000-000000000008','bb000001-2222-4000-a000-000000000002','Chả Giò Rế','Chả giòn vỏ rế ăn kèm rau sống và nước mắm.', 20000,'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?w=500',true,4.3,7400,'ca000001-0000-4000-a000-000000000004'),
('cc000002-0001-4000-a000-000000000009','bb000001-2222-4000-a000-000000000002','Trà Đá','Trà đá truyền thống mát lạnh giải nhiệt.', 5000,'https://images.unsplash.com/photo-1556679343-c7306c1976bc?w=500',true,4.0,30000,'ca000001-0000-4000-a000-000000000003'),
('cc000002-0001-4000-a000-000000000010','bb000001-2222-4000-a000-000000000002','Nước Chanh Muối','Chanh muối đập đá, vị chua mặn ngọt sảng khoái.', 18000,'https://images.unsplash.com/photo-1621263764928-df1444c5e859?w=500',true,4.5,5200,'ca000001-0000-4000-a000-000000000003');
